import 'dart:convert';
import 'package:shared_preferences/shared_preferences.dart';
import '../domain/models.dart';
class AppStore { static const key='psy_tools_data_v1'; Map<String,dynamic> data={'schemaVersion':1,'wheels':<Map<String,dynamic>>[],'scores':<Map<String,dynamic>>[],'journal':<Map<String,dynamic>>[],'settings':{}}; Future<void> load() async { final p=await SharedPreferences.getInstance(); final raw=p.getString(key); if(raw!=null)data=Map<String,dynamic>.from(jsonDecode(raw)); } Future<void> save() async { final p=await SharedPreferences.getInstance(); await p.setString(key,jsonEncode(data)); } List<Wheel> wheels()=>((data['wheels'] as List?)??[]).map((e)=>Wheel.fromJson(Map<String,dynamic>.from(e))).toList(); Future<void> replaceFromBackup(Map<String,dynamic> backup) async { if(backup['schemaVersion'] is! int||backup['wheels'] is! List||backup['journal'] is! List)throw const FormatException('Invalid PSY-TOOLS backup'); data=Map<String,dynamic>.from(backup); await save(); } }
